sys_ws_operation.operation_script:
(function process(/*RESTAPIRequest*/ request, /*RESTAPIResponse*/ response) {

    var responseBody = {};
    var caseNumber = request.queryParams.case_number;

    // -------------------------
    // Validate Input
    // -------------------------
    if (!caseNumber) {
        responseBody.status = "ERROR! Please specify a case_number";
        response.setStatus(400);
        response.setBody(responseBody);
        return;
    }

    // -------------------------
    // Query sn_customerservice_financelink table
    // -------------------------
    var gr = new GlideRecord("sn_customerservice_financelink");
    gr.addQuery("number", caseNumber);
    gr.query();

    if (gr.next()) {
        responseBody.status = gr.getDisplayValue("state");
    } else {
        responseBody.status = "Cannot locate Case Number: " + caseNumber;
    }

    response.setBody(responseBody);

})(request, response);
